var w=Main.World!; var b=w.Voyage.Position; var cam=Main.GetViewport().GetCamera3D()!; Godot.Vector2 sp=default; double gx=0,gz=0; bool ok=false;
for(int r=15;r<=45 && !ok;r+=5){ for(int k=0;k<24 && !ok;k++){ double a=k*System.Math.PI/12.0; double tx=b.X+System.Math.Cos(a)*r, tz=b.Z+System.Math.Sin(a)*r; var s=cam.UnprojectPosition(new Godot.Vector3((float)tx,0f,(float)tz)); if(s.X<40||s.Y<80||s.X>1880||s.Y>960) continue; if(Main.Picker.Pick(s).Target!=DemoFactory.Prototypes.BeastArena.Ui.PickTarget.Empty) continue; var o=cam.ProjectRayOrigin(s); var n=cam.ProjectRayNormal(s); if(System.Math.Abs(n.Y)<1e-6) continue; double t=-o.Y/n.Y; if(t<=0||t>900) continue; double hx=o.X+n.X*t, hz=o.Z+n.Z*t; if(System.Math.Sqrt((hx-tx)*(hx-tx)+(hz-tz)*(hz-tz))>2.5) continue; sp=s; gx=hx; gz=hz; ok=true; } }
if(!ok) throw new System.Exception("no-empty-ground-for-sailto");
Input.ParseInputEvent(new Godot.InputEventMouseButton{ButtonIndex=Godot.MouseButton.Right,Pressed=true,Position=sp});
Input.ParseInputEvent(new Godot.InputEventMouseButton{ButtonIndex=Godot.MouseButton.Right,Pressed=false,Position=sp});
return "sp="+sp+" g="+gx.ToString("0.0")+","+gz.ToString("0.0");

